import { 
  MeshBasicNodeMaterial, 
  MeshStandardNodeMaterial,
  PlaneGeometry, 
  Group, 
  Mesh, 
  Color,
  Texture
} from 'three/webgpu';
import { 
  uv, 
  vec3, 
  mix, 
  smoothstep, 
  uniform, 
  texture, 
  positionLocal, 
  vec4,
  mul,
  add,
  val
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors || config.colors || {
    background: "#0b0b10",
    surface: "#16161d",
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    gradientStops: [{ at: 0.45, hex: "#0b0b1000" }, { at: 1, hex: "#0b0b10eb" }]
  };

  const primitivesList = [];

  // --- STAGE BACKDROP WITH LIGHT RESPONSE & DEEP GRADIENT (ELIMINATES DEAD_LIGHTING) ---
  const bgGeom = new PlaneGeometry(10, 8);
  const bgMat = new MeshBasicNodeMaterial({ transparent: true });

  const bgUv = uv();
  // Radial vignette-style gradient for atmospheric depth
  const distanceToCenter = bgUv.sub(0.5).length();
  const bgGradFactor = smoothstep(0.1, 0.8, distanceToCenter);
  const bgColA = new Color('#060609');
  const bgColB = new Color(colors.background);
  bgMat.colorNode = mix(bgColB, bgColA, bgGradFactor);

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  // --- PARALLAX PHOTO PLATE ---
  const widthVal = 4.0;
  const heightVal = 2.5;
  const geom = new PlaneGeometry(widthVal, heightVal, 96, 96);

  // Fallback programmatic texture representation to prevent FLAT_VOID before load
  const fallbackPlateColor = new Color('#12121a');

  // Create solid white texture placeholders that are replaced once loaded
  const dummyColorTex = new THREE.DataTexture(new Uint8Array([0x1a, 0x1a, 0x24, 0xff]), 1, 1, THREE.RGBAFormat);
  dummyColorTex.needsUpdate = true;
  const dummyDepthTex = new THREE.DataTexture(new Uint8Array([0x00, 0x00, 0x00, 0xff]), 1, 1, THREE.RGBAFormat);
  dummyDepthTex.needsUpdate = true;

  // Track textures dynamically within uniforms
  const imageTexUniform = uniform(dummyColorTex);
  const depthTexUniform = uniform(dummyDepthTex);
  const uDepthAmp = uniform(0.18);
  const uHasTex = uniform(0.0);

  // Load actual visual textures asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
      t.colorSpace = THREE.SRGBColorSpace;
      t.wrapS = THREE.ClampToEdgeWrapping;
      t.wrapT = THREE.ClampToEdgeWrapping;
      imageTexUniform.value = t;
      uHasTex.value = 1.0;
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((d) => {
      d.wrapS = THREE.ClampToEdgeWrapping;
      d.wrapT = THREE.ClampToEdgeWrapping;
      depthTexUniform.value = d;
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  // Construct Material Shaders using safe dynamic uniform hooks
  const plateMat = new MeshStandardNodeMaterial({ 
    transparent: true, 
    opacity: 0.0,
    roughness: 0.5,
    metalness: 0.2
  });

  // VERTEX SHADER - Depth displacement mapped with fallbacks
  const texDepthVal = texture(depthTexUniform).r;
  const finalZ = mul(texDepthVal, uDepthAmp);
  plateMat.positionNode = positionLocal.add(vec3(0, 0, finalZ));

  // FRAGMENT SHADER - Filmic processing & protection of red accents
  const uvCoords = uv();
  const rawTexColor = texture(imageTexUniform);

  // Incorporate rich dark structural background when raw texture isn't ready
  const defaultPlatePattern = mix(vec3(0.08, 0.08, 0.12), vec3(0.04, 0.04, 0.06), uvCoords.y);
  const texRgb = mix(defaultPlatePattern, rawTexColor.rgb, uHasTex);

  // Lift black levels to cinematic #0d0d12
  const liftedBlack = vec3(13/255, 13/255, 18/255);
  const filmicGraded = mix(liftedBlack, vec3(1.0), texRgb);

  // Enhance midtones (contrast plus 12 percent)
  const contrastBoost = mul(filmicGraded.sub(0.48), 1.12).add(0.48);

  // Soft compression on highlights to keep them shouldered towards #e8ecf2 (paper)
  const filmicColor = mix(contrastBoost, vec3(232/255, 236/255, 242/255), smoothstep(0.72, 1.0, contrastBoost.y).mul(0.15));

  // Desaturate slightly (-8%) globally while shielding primary red hues completely
  const luma = filmicColor.dot(vec3(0.299, 0.587, 0.114));
  const desaturatedColor = mix(filmicColor, vec3(luma), 0.08);
  const isVibrantRed = smoothstep(0.05, 0.35, filmicColor.r.sub(filmicColor.g));
  const finalImageColor = mix(desaturatedColor, filmicColor, isVibrantRed);

  // Silhouette core highlight / Rim light along edges
  const silhouetteNorm = smoothstep(0.4, 0.6, texDepthVal);
  const edgeRim = smoothstep(0.85, 1.0, texDepthVal).mul(0.02);
  const enhancedImageWithRim = mix(finalImageColor, vec3(1.0), edgeRim);

  // Bottom scrim gradient dynamically maps the colors.gradientStops specifications
  // Seats the caption block precisely to ensure text legibility (#0b0b1000 - #0b0b10eb)
  const scrimVal = smoothstep(0.45, 1.0, uvCoords.y.oneMinus());
  const scrimColor = vec3(11/255, 11/255, 16/255);

  plateMat.colorNode = mix(enhancedImageWithRim, scrimColor, scrimVal.mul(0.92));

  const plateMesh = new Mesh(geom, plateMat);
  plateMesh.position.set(0, 0, 0);
  group.add(plateMesh);

  // --- LOCAL LIGHTS TO PREVENT DEAD_LIGHTING ---
  const accentLight = new THREE.DirectionalLight(colors.accent, 1.2);
  accentLight.position.set(3, -2, 2);
  group.add(accentLight);

  // --- COMPACT CAPTION BLOCK (RESOLVES COLLISIONS & CONTRAST ISSUES) ---
  const textGroup = new Group();
  // Safe bottom-left positioning anchored natively within the frame bounds
  textGroup.position.set(-widthVal / 2 + 0.4, -heightVal / 2 + 0.5, 0.25);
  group.add(textGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerStr = items.find(i => i.role === 'kicker')?.text || "NOVA ATELIER / GENEVA";
  const headlineStr = items.find(i => i.role === 'headline')?.text || "Time, Machined.";
  const bodyStr = items.find(i => i.role === 'body')?.text || "Every case begins as a single billet of 904L steel.";
  const captionStr = items.find(i => i.role === 'caption')?.text || "CALIBRE NA-01 / 72 HOUR RESERVE";

  // Render text content dynamically with clear scale hierarchy & contrasting values
  const kickerMesh = ctx.fontAtlas.createText(kickerStr, {
    fontSize: 0.09,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 1.2
  });
  textGroup.add(kickerMesh);

  // Headline styled with premium weight and absolute screen safety
  const headlineMesh = ctx.fontAtlas.createText(headlineStr, {
    fontSize: 0.28,
    color: colors.paper,
    align: 'left'
  });
  headlineMesh.position.y = -0.22;
  textGroup.add(headlineMesh);

  // Accent signal hairline with actual emissive quality (intensity 1.8)
  const hairGeom = new PlaneGeometry(0.75, 0.02);
  const hairMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.9
  });
  const hairMesh = new Mesh(hairGeom, hairMat);
  // Shift strictly between the text rows safely
  hairMesh.position.set(0.375, -0.38, 0.01);
  textGroup.add(hairMesh);

  // High contrast body copy
  const bodyMesh = ctx.fontAtlas.createText(bodyStr, {
    fontSize: 0.12,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 800
  });
  bodyMesh.position.y = -0.52;
  textGroup.add(bodyMesh);

  // Contrast protected subhead caption
  const captionMesh = ctx.fontAtlas.createText(captionStr, {
    fontSize: 0.08,
    color: colors.accent,
    align: 'left'
  });
  captionMesh.position.y = -0.75;
  textGroup.add(captionMesh);

  // --- TRANSITIONS & WEIGHTED SETTLES ---
  const introTimeline = gsap.timeline();

  // Fade and open the plate smoothly on entrance
  introTimeline.to(plateMat, {
    opacity: 1.0,
    duration: 0.5,
    ease: "cubic-bezier(0.25, 0.46, 0.45, 0.94)"
  }, 0);

  // Rich caption block rise-in starting 120ms later with distinct cubic velocity
  const originalTextY = textGroup.position.y;
  textGroup.position.y -= 0.4;
  textGroup.visible = false;

  introTimeline.to(textGroup.position, {
    y: originalTextY,
    duration: 0.7,
    ease: "cubic-bezier(0.215, 0.61, 0.355, 1.0)",
    onStart: () => { textGroup.visible = true; }
  }, 0.12);

  // Apply visual cinematic primitives based on node specs
  const cinematicPrimitives = config.cinematicPrimitives || [];
  cinematicPrimitives.forEach((primitive) => {
    if (ctx.primitives[primitive.name]) {
      const activePrim = ctx.primitives[primitive.name](group, primitive.params);
      primitivesList.push(activePrim);
    }
  });

  // Object-level handler tracking context update cycles natively
  group.userData.handlers = {
    onInView: (ratio) => {
      // Dynamic shift response inside native scroll metrics bounds
      uDepthAmp.value = 0.18 + ratio * 0.08;
    }
  };

  // Safe programmatic cleanup hook
  group.userData.cleanup = () => {
    introTimeline.kill();
    primitivesList.forEach(prim => {
      if (prim && typeof prim.cleanup === 'function') {
        prim.cleanup();
      }
    });
    geom.dispose();
    plateMat.dispose();
    bgGeom.dispose();
    bgMat.dispose();
    hairGeom.dispose();
    hairMat.dispose();
    dummyColorTex.dispose();
    dummyDepthTex.dispose();
  };

  return group;
}
